/**
 * 1. CLIENT SCRIPT (Runs in the browser)
 * Triggers every time the 'Urgency' field changes on the Incident form.
 */
export const AlertHighUrgency = ClientScript({
    $id: Now.ID['cs_urgency_alert'],
    name: 'Alert High Urgency',
    table: 'incident',
    active: true,
    global: true,
    ui_type: 'all',
    type: 'onChange',
    field: 'urgency', // Listens specifically to the urgency field changing
    description: 'Provides a browser alert and console log when urgency is set to High.',
    script: script`function onChange(control, oldValue, newValue, isLoading, isTemplate) {
        if (isLoading || newValue === '') {
            return;
        }

        // '1' is the backend choice value for 'High' urgency in ServiceNow
        if (newValue === '1') {
            // Pops up a browser notification banner at the top of the form
            g_form.addErrorMessage('⚠️ Warning: You have set this incident to HIGH urgency!');
            
            // Outputs directly to your browser's inspect developer tools console (F12)
            console.log('Client Script triggered: Urgency changed from ' + oldValue + ' to ' + newValue);
        }
    }`
});
/**
 * 2. BUSINESS RULE (Runs on the cloud server)
 * Triggers after an incident record is updated in the database.
 */
export const LogIncidentWorknotes = BusinessRule({
    $id: Now.ID['br_log_worknotes'],
    name: 'Log Worknotes Addition',
    table: 'incident',
    active: true,
    when: 'after',
    action: ['update'], // Runs exclusively on record updates
    order: 100,
    addMessage: true,
    message: 'System validated: Your work notes were saved successfully.',
    description: 'Logs a system message on the server when work notes are updated.',
    filterCondition: 'work_notesVALCHANGES^EQ',
    script: script`function onAfter(current, previous) {
        console.log("FLUET LOGS: ", current.state)
    }`
});

export const ChangeSubCatgoryAutoFill = ClientScript({
    // 🛠️ FIX 1: Change ID from 'br0' to a unique client script key name
    $id: Now.ID['cs_category_autofill'], 
    name: 'Sub Category autoFill after Catgeory',
    table: 'incident',
    active: true,
    global: true,
    ui_type: 'all',
    type: 'onChange',
    field: 'category',
    description: 'When Category Changes to Software Subcategory will be Operating System',
    script: script`function onChange(control, oldValue, newValue, isLoading, isTemplate) {
        
        // 🛠️ FIX 2: Move logs HERE so they print even if the form is loading
        console.log('=== [DEBUG CONSOLE] onChange Triggered ===');
        console.log('isLoading state:', isLoading);
        console.log('Old Value: ', oldValue);
        console.log('New Value: ', newValue);
        console.log('==========================================');

        if (newValue === 'software') {
            g_form.setValue('subcategory', 'operating system');
            g_form.showFieldMsg('subcategory', 'Auto-populated to Operating System.', 'info');
        }
    }`
});




